import java.io.*;import java.util.*;public class Main{public static void main(String[]args)throws IOException{BufferedReader br=new BufferedReader(new InputStreamReader(System.in));StringBuilder sb=new StringBuilder();int T=Integer.parseInt(br.readLine().trim());for(int t=0;t<T;t++){int p=Integer.parseInt(br.readLine().trim());int cnt=p/2048;int rem=p%2048;cnt+=Integer.bitCount(rem);sb.append(cnt);if(t+1<T)sb.append('\n');}System.out.print(sb.toString());}}